import{_ as s,C as i,c as n,o as a,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Vendor price lists","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/products/vendor-price-lists.md","filePath":"master/supply-chain/purchase/products/vendor-price-lists.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/purchase/products/vendor-price-lists.md"};function d(c,e,h,p,u,g){const r=i("ImagePopup");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="vendor-price-lists" tabindex="-1">Vendor price lists <a class="header-anchor" href="#vendor-price-lists" aria-label="Permalink to &quot;Vendor price lists&quot;">​</a></h1><p>A vendor price list records what each vendor charges for a product. You can store different prices for different quantities, dates and currencies. When you add the product to an RFQ, Aureus reads the list and fills the price for you.</p><blockquote><p><strong>In simple words:</strong> A price sheet for each vendor, kept next to the product.</p></blockquote><p>You can reach the same rows in two places.</p><ol><li><code>Purchase → Configurations → Vendor Price Lists</code> shows every row for every product. The page header shows <strong>Product Suppliers</strong>. It is the same list.</li><li>The <strong>Vendors</strong> tab of a product shows only the rows for that product.</li></ol><p>No setting is needed. The menu is always there.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has the columns <strong>Vendor</strong>, <strong>Product</strong>, <strong>Company</strong>, <strong>Unit Price</strong> and <strong>Currency</strong>. Use <strong>Group by</strong> to group by <strong>Vendor</strong>, <strong>Product</strong>, <strong>Created At</strong> or <strong>Updated At</strong>.</p>',8)),o(r,{src:"/images1/purchase/vp_list.png",alt:"Vendor Price Lists page with three rows for FreshFoods Wholesale showing product, unit price and currency"}),e[1]||(e[1]=t('<h2 id="create-a-vendor-price" tabindex="-1">Create a vendor price <a class="header-anchor" href="#create-a-vendor-price" aria-label="Permalink to &quot;Create a vendor price&quot;">​</a></h2><ol><li>Go to <code>Purchase → Configurations → Vendor Price Lists</code>.</li><li>Click <strong>New Vendor Price</strong>.</li><li>Fill the <strong>General</strong> section.</li></ol>',2)),o(r,{src:"/images1/purchase/vp_form_general.png",alt:"New vendor price form General section with vendor FreshFoods Wholesale and product name SSD 512GB 2.5in"}),e[2]||(e[2]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Vendor:</em></strong> The company that sells it. Required.</li><li><strong><em>Vendor Product Name:</em></strong> The name the vendor uses. It prints on the RFQ. Leave it blank to use your own name.</li><li><strong><em>Vendor Product Code:</em></strong> The vendor&#39;s code. It prints on the RFQ. Leave it blank to use your own code.</li><li><strong><em>Delivery Lead Time (Days):</em></strong> Days from order confirmation to goods in your warehouse. The default is 1.</li></ul><ol start="4"><li>Fill the <strong>Prices</strong> section.</li></ol>',3)),o(r,{src:"/images1/purchase/vp_form_prices.png",alt:"Prices section with product SSD 512GB, quantity 10, unit price 3300, validity dates and discount"}),e[3]||(e[3]=t(`<h3 id="prices" tabindex="-1">Prices <a class="header-anchor" href="#prices" aria-label="Permalink to &quot;Prices&quot;">​</a></h3><ul><li><strong><em>Product:</em></strong> The product this price applies to. On a product&#39;s <strong>Vendors</strong> tab this field is hidden, because the product is known. With variants, you choose the variant.</li><li><strong><em>Quantity:</em></strong> The minimum quantity that earns this price. The default is 0.</li><li><strong><em>Unit Price:</em></strong> Price for one unit, in the unit of measure of the product.</li><li><strong><em>Currency:</em></strong> The currency of the vendor price. Required. It defaults to your company currency.</li><li><strong><em>Valid From:</em></strong> and <strong><em>Valid Until:</em></strong> The dates of the price period. Leave both empty for a price with no end.</li><li><strong><em>Discount (%):</em></strong> An optional percentage off this price.</li><li><strong><em>Company:</em></strong> The company that owns the row. It defaults to the current company.</li></ul><ol start="5"><li>Click <strong>Create</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Fill <strong>Valid From</strong> and <strong>Valid Until</strong> for seasonal deals. They tell your team when the quote ends.</p></div><h2 id="price-tiers-by-quantity" tabindex="-1">Price tiers by quantity <a class="header-anchor" href="#price-tiers-by-quantity" aria-label="Permalink to &quot;Price tiers by quantity&quot;">​</a></h2><p>Add one row per tier. Each row sets the lowest quantity for its price.</p><table tabindex="0"><thead><tr><th>Vendor</th><th>Product</th><th>Quantity</th><th>Unit Price</th></tr></thead><tbody><tr><td>FreshFoods Wholesale</td><td>SSD 512GB</td><td>1</td><td>3500</td></tr><tr><td>FreshFoods Wholesale</td><td>SSD 512GB</td><td>10</td><td>3300</td></tr><tr><td>FreshFoods Wholesale</td><td>SSD 512GB</td><td>50</td><td>3100</td></tr></tbody></table><h2 id="how-a-line-price-is-picked" tabindex="-1">How a line price is picked <a class="header-anchor" href="#how-a-line-price-is-picked" aria-label="Permalink to &quot;How a line price is picked&quot;">​</a></h2><p>When you choose a product on an order line, Aureus follows these steps.</p><ol><li>It looks at the price rows of that product.</li><li>If you chose a vendor on the order, it keeps only that vendor&#39;s rows.</li><li>It keeps rows whose <strong>Quantity</strong> is at or below the line quantity.</li><li>It takes the best matching row and uses its <strong>Unit Price</strong>, converted to the order currency.</li><li>If no row matches, it uses the product <strong>Cost</strong>, or the product <strong>Price</strong> when cost is empty.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Product + Vendor + Quantity  →  matching price rows  →  Unit Price on the line</span></span>
<span class="line"><span>                                   no match         →  Cost (then Price)</span></span></code></pre></div><p>Change the line <strong>Quantity</strong> and the price is checked again. With 15 units of SSD 512GB, the row for 10 units applies.</p>`,12)),o(r,{src:"/images1/purchase/vp_rfq_line.png",alt:"RFQ line for SSD 512GB with quantity 15 and unit price 3300 taken from the 10 unit tier"}),e[4]||(e[4]=t('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You can always type over the <strong>Unit Price</strong> on a line. The vendor price list only gives the starting value.</p></div><h2 id="edit-or-delete-a-price" tabindex="-1">Edit or delete a price <a class="header-anchor" href="#edit-or-delete-a-price" aria-label="Permalink to &quot;Edit or delete a price&quot;">​</a></h2><ol><li>Open the row from the list or from the product <strong>Vendors</strong> tab.</li><li>Click <strong>Edit</strong>, change the values and save.</li><li>To remove a row, use the delete action on the row.</li></ol><p><strong>Behind the scenes:</strong> Price rows are stored per product and vendor. The list in Configurations and the product tab show the same records.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./configure-product.html">Configure a product</a></li><li><a href="./../orders/quotations.html">Quotations</a></li><li><a href="./product-configuration.html">Product configuration</a></li></ul>',6))])}const _=s(l,[["render",d]]);export{f as __pageData,_ as default};
